/* selectExportExOlExportEndCheck */
SELECT	COUNT(*)
FROM	KEP_EXP_CIHD
WHERE	1=1
AND		BUYER = #{BUYER}
AND		PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
AND		COMPLETE_MARK = 'Y'
AND		STATUS IN ('C', 'R')
AND		CI_NO IN	(
							SELECT	CI_NO
							FROM	KEP_EXP_BLDT
							WHERE	1=1
							AND		BUYER = #{BUYER}
							AND		PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
							AND		BL_NO = #{BL_NO}
)

