/* updateExportExOlExportProgressHd */ UPDATE KEP_EXP_CIHD A SET EXP_REPORT_DATE = #{EXP_REPORT_DATE}, EXP_SHIP_DATE = #{EXP_SHIP_DATE}, ENTRY_EXCHANGE_RATE = #{ENTRY_EXCHANGE_RATE}, IMAGE_KEY = #{IMAGE_KEY}, CI_IMAGE_KEY = #{CI_IMAGE_KEY}, CHANGE_DATE = SYSDATE, CHANGE_USER_ID = #{st_user_id}, STATUS = 'R'
,COMPLETE_MARK = 'Y'
WHERE PKG_COMPANY_CODE = #{st_pkg_cmpy_no} AND BUYER = #{BUYER} AND CI_NO = #{CI_NO}


/* updateExportExOlExportProgressBlHd */
UPDATE	KEP_EXP_BLHD A
SET		A.CHANGE_DATE = SYSDATE
			,A.CHANGE_USER_ID = #{st_user_id}



	, RESULT_FLAG ='N'
	, RESULT_MSG = NULL
	, RESULT_DATE = NULL
	, BUYER_SHIPPING_NO = NULL



WHERE	A.PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
AND	(A.BUYER, A.PKG_COMPANY_CODE, A.BL_NO) IN (
	SELECT BLDT.BUYER, BLDT.PKG_COMPANY_CODE, BLDT.BL_NO
	FROM KEP_EXP_BLDT BLDT
	WHERE BLDT.BUYER = #{BUYER} 
	AND BLDT.CI_NO = #{CI_NO} 
)


/* deleteBlExportExOlExportProgressBldt */
DELETE	KEP_EXP_BLDT
WHERE	PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
AND		BUYER = #{BUYER}
AND		BL_NO = #{BL_NO}


/* deleteBlExportExOlExportProgressBlhd */
DELETE	KEP_EXP_BLHD
WHERE	PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
AND		BUYER = #{BUYER}
AND		BL_NO = #{BL_NO}


/* deleteCiExportExOlExportProgressCidt */
DELETE	KEP_EXP_CIDT A
WHERE	PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
AND		BUYER = #{BUYER}
AND		CI_NO = #{CI_NO}


/* deleteCiExportExOlExportProgressCihd */
DELETE	KEP_EXP_CIHD A
WHERE	PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
AND		BUYER = #{BUYER}
AND		CI_NO = #{CI_NO}


/* updateExportExOlExportProgressCihd */
UPDATE	KEP_EXP_CIHD A
SET		BL_COMPLETE_MARK = 'N',
			CHANGE_DATE = SYSDATE,
			CHANGE_USER_ID = #{st_user_id},
			STATUS = 'R'
WHERE	PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
AND		BUYER = #{BUYER}
AND		CI_NO IN ( SELECT CI_NO FROM KEP_EXP_BLDT
					WHERE BUYER = #{BUYER}
					AND BL_NO = #{BL_NO}
				  )


		/* updateExportExOlExportIcomivdt */
		MERGE	INTO	ICOMIVDT A
     	USING	(SELECT	CIDT.BUYER,
      							CIDT.INV_NO,
      							CIDT.INV_SEQ,
								SUM(CIDT.INV_QTY)INV_QTY
					FROM	KEP_EXP_CIDT CIDT
					WHERE	CIDT.PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
             		AND		CIDT.BUYER = #{BUYER}
             		AND		CIDT.CI_NO = #{CI_NO}
             		GROUP BY CIDT.BUYER,
      							CIDT.INV_NO,
      							CIDT.INV_SEQ
		) B
        ON	(		A.BUYER = B.BUYER
				AND	A.INV_NO = B.INV_NO
            	AND	A.INV_SEQ = B.INV_SEQ
		)
		WHEN	MATCHED
		THEN		UPDATE SET A.PKG_CI_QTY = A.PKG_CI_QTY- B.INV_QTY


		/* updateExportExOlExportWmsivdt */
		MERGE	INTO	WMSIVDT A
     	USING	(SELECT	CIDT.BUYER,
      							CIDT.INV_NO,
      							CIDT.INV_SEQ,
								SUM(CIDT.INV_QTY)INV_QTY
					FROM	KEP_EXP_CIDT CIDT
					WHERE	CIDT.PKG_COMPANY_CODE = #{st_pkg_cmpy_no}
             		AND		CIDT.BUYER = #{BUYER}
             		AND		CIDT.CI_NO = #{CI_NO}
             		GROUP BY CIDT.BUYER,
      							CIDT.INV_NO,
      							CIDT.INV_SEQ
		) B
        ON	(		A.BUYER = B.BUYER
				AND	A.INV_NO = B.INV_NO
            	AND	A.INV_SEQ = B.INV_SEQ
		)
		WHEN	MATCHED
		THEN		UPDATE SET A.PKG_CI_QTY = A.PKG_CI_QTY- B.INV_QTY
